components.css:
.ds-btn-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  height: 52px;
  padding: 0 26px;
  border-radius: 11px;
  font-family: 'Hanken Grotesk', system-ui, sans-serif;
  font-weight: 600;
  font-size: 15.5px;
  letter-spacing: -0.01em;
  border: 1px solid transparent;
  cursor: pointer;
  color: #07070c;
  background: linear-gradient(110deg, #7c5cff, #22d3ee 52%, #ff4d9d);
  background-size: 160% 160%;
  box-shadow: 0 8px 30px -8px color-mix(in oklab, #7c5cff 70%, transparent);
  transition: transform 0.35s cubic-bezier(0.2,0.8,0.2,1), box-shadow 0.35s;
  white-space: nowrap;
}
.ds-btn-primary:hover {
  transform: translateY(-2px);
  box-shadow: 0 18px 50px -10px color-mix(in oklab, #22d3ee 75%, transparent);
}
.ds-btn-primary:active {
  transform: translateY(1px) scale(0.99);
}
.ds-btn-primary:focus-visible {
  outline: 2px solid #7c5cff;
  outline-offset: 3px;
}
.ds-btn-arrow {
  transition: transform 0.35s cubic-bezier(0.2,0.8,0.2,1);
}
.ds-btn-primary:hover .ds-btn-arrow {
  transform: translate(3px,-3px);
}

.ds-btn-ghost {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  height: 52px;
  padding: 0 26px;
  border-radius: 11px;
  font-family: 'Hanken Grotesk', system-ui, sans-serif;
  font-weight: 600;
  font-size: 15.5px;
  letter-spacing: -0.01em;
  border: 1px solid rgba(255,255,255,0.16);
  cursor: pointer;
  color: #f3f2f8;
  background: rgba(255,255,255,0.035);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  transition: transform 0.35s cubic-bezier(0.2,0.8,0.2,1), background 0.25s, border-color 0.25s;
  white-space: nowrap;
}
.ds-btn-ghost:hover {
  background: rgba(255,255,255,0.06);
  border-color: rgba(243,242,248,0.4);
  transform: translateY(-2px);
}
.ds-btn-ghost:active {
  transform: translateY(1px) scale(0.99);
}
.ds-btn-ghost:focus-visible {
  outline: 2px solid #7c5cff;
  outline-offset: 3px;
}

.ds-tag {
  display: inline-block;
  font-family: 'Space Mono', ui-monospace, monospace;
  font-size: 11.5px;
  letter-spacing: 0.04em;
  color: rgba(243,242,248,0.64);
  padding: 5px 11px;
  border: 1px solid rgba(255,255,255,0.10);
  border-radius: 999px;
  background: rgba(255,255,255,0.035);
}

.ds-eyebrow {
  font-family: 'Space Mono', ui-monospace, monospace;
  font-size: 12px;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: rgba(243,242,248,0.40);
  display: inline-flex;
  align-items: center;
  gap: 10px;
}
.ds-eyebrow::before {
  content: '';
  width: 22px;
  height: 1px;
  background: linear-gradient(110deg, #7c5cff, #22d3ee 52%, #ff4d9d);
  flex-shrink: 0;
}

.ds-svc-card {
  position: relative;
  overflow: hidden;
  border: 1px solid rgba(255,255,255,0.10);
  border-radius: 16px;
  background: linear-gradient(180deg, rgba(255,255,255,0.035), transparent), #07070c;
  padding: 32px;
  min-height: 280px;
  display: flex;
  flex-direction: column;
  transition: transform 0.5s cubic-bezier(0.2,0.8,0.2,1), border-color 0.4s;
}
.ds-svc-card:hover {
  transform: translateY(-4px);
  border-color: rgba(255,255,255,0.16);
}
.ds-svc-head-row {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  margin-bottom: 18px;
}
.ds-svc-ico {
  width: 46px;
  height: 46px;
  border-radius: 12px;
  display: grid;
  place-items: center;
  background: rgba(255,255,255,0.06);
  border: 1px solid rgba(255,255,255,0.10);
  color: #f3f2f8;
  flex-shrink: 0;
}
.ds-svc-num {
  font-family: 'Space Mono', ui-monospace, monospace;
  font-size: 12px;
  color: rgba(243,242,248,0.40);
  letter-spacing: 0.1em;
}
.ds-svc-title {
  font-family: 'Schibsted Grotesk', system-ui, sans-serif;
  font-size: clamp(1.4375rem, 2.4vw, 1.875rem);
  font-weight: 700;
  letter-spacing: -0.03em;
  line-height: 0.98;
  color: #f3f2f8;
  margin: 0 0 12px;
  text-wrap: balance;
}
.ds-svc-tagline {
  font-family: 'Schibsted Grotesk', system-ui, sans-serif;
  font-weight: 600;
  font-size: 15px;
  letter-spacing: -0.01em;
  background: linear-gradient(110deg, #7c5cff, #22d3ee 52%, #ff4d9d);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  margin: 0 0 14px;
}
.ds-svc-desc {
  font-family: 'Hanken Grotesk', system-ui, sans-serif;
  color: rgba(243,242,248,0.64);
  font-size: 15.5px;
  line-height: 1.55;
  margin: 0 0 22px;
}
.ds-svc-tags {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  margin-top: auto;
}
.ds-tag {
  display: inline-block;
  font-family: 'Space Mono', ui-monospace, monospace;
  font-size: 11.5px;
  letter-spacing: 0.04em;
  color: rgba(243,242,248,0.64);
  padding: 5px 11px;
  border: 1px solid rgba(255,255,255,0.10);
  border-radius: 999px;
  background: rgba(255,255,255,0.035);
}

.ds-nav {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 24px;
  border-bottom: 1px solid transparent;
  transition: background 0.4s, backdrop-filter 0.4s, border-color 0.4s, padding 0.4s;
}
.ds-nav--scrolled {
  background: color-mix(in oklab, #07070c 72%, transparent);
  backdrop-filter: blur(18px) saturate(140%);
  -webkit-backdrop-filter: blur(18px) saturate(140%);
  border-bottom-color: rgba(255,255,255,0.10);
  padding-block: 10px;
}
.ds-brand {
  text-decoration: none;
  display: flex;
  align-items: center;
  gap: 13px;
}
.ds-nav-word {
  font-family: 'Schibsted Grotesk', system-ui, sans-serif;
  font-weight: 800;
  letter-spacing: -0.045em;
  line-height: 1;
  font-size: 22px;
  display: flex;
}
.ds-three { color: #f3f2f8; }
.ds-dimos {
  background: linear-gradient(110deg, #7c5cff, #22d3ee 52%, #ff4d9d);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}
.ds-nav-links {
  display: flex;
  align-items: center;
  gap: 4px;
}
.ds-nav-link {
  font-family: 'Hanken Grotesk', system-ui, sans-serif;
  font-size: 14.5px;
  font-weight: 500;
  color: rgba(243,242,248,0.64);
  padding: 9px 14px;
  border-radius: 9px;
  text-decoration: none;
  transition: color 0.2s, background 0.2s;
}
.ds-nav-link:hover {
  color: #f3f2f8;
  background: rgba(255,255,255,0.035);
}
.ds-btn-nav-cta {
  margin-left: 8px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 40px;
  padding: 0 18px;
  border-radius: 11px;
  font-family: 'Hanken Grotesk', system-ui, sans-serif;
  font-weight: 600;
  font-size: 14px;
  letter-spacing: -0.01em;
  border: 1px solid transparent;
  cursor: pointer;
  color: #07070c;
  background: linear-gradient(110deg, #7c5cff, #22d3ee 52%, #ff4d9d);
  box-shadow: 0 6px 20px -6px color-mix(in oklab, #7c5cff 70%, transparent);
  transition: transform 0.35s cubic-bezier(0.2,0.8,0.2,1), box-shadow 0.35s;
}
.ds-btn-nav-cta:hover {
  transform: translateY(-1px);
  box-shadow: 0 12px 30px -8px color-mix(in oklab, #22d3ee 75%, transparent);
}

.ds-work-card {
  position: relative;
  border: 1px solid rgba(255,255,255,0.10);
  border-radius: 16px;
  overflow: hidden;
  background: #0b0b13;
  transition: transform 0.5s cubic-bezier(0.2,0.8,0.2,1), border-color 0.4s;
  cursor: pointer;
}
.ds-work-card:hover {
  transform: translateY(-5px);
  border-color: rgba(255,255,255,0.16);
}
.ds-work-thumb {
  position: relative;
  aspect-ratio: 16 / 10;
  overflow: hidden;
  background: repeating-linear-gradient(135deg, color-mix(in oklab, #7c5cff 9%, #0b0b13) 0 14px, #0b0b13 14px 28px);
}
.ds-work-thumb::after {
  content: attr(data-ph);
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  font-family: 'Space Mono', ui-monospace, monospace;
  font-size: 12px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: rgba(243,242,248,0.40);
}
.ds-work-sheen {
  position: absolute;
  inset: 0;
  background: radial-gradient(60% 80% at 30% 0%, color-mix(in oklab, #22d3ee 26%, transparent), transparent 55%);
  opacity: 0;
  transition: opacity 0.5s;
}
.ds-work-card:hover .ds-work-sheen { opacity: 1; }
.ds-work-meta {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 20px 22px;
  gap: 16px;
}
.ds-work-cat {
  display: block;
  font-family: 'Space Mono', ui-monospace, monospace;
  font-size: 11px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: rgba(243,242,248,0.40);
  margin-bottom: 7px;
}
.ds-work-title {
  font-family: 'Schibsted Grotesk', system-ui, sans-serif;
  font-size: clamp(1.25rem, 2vw, 1.625rem);
  font-weight: 700;
  letter-spacing: -0.03em;
  line-height: 0.98;
  color: #f3f2f8;
  margin: 0;
}
.ds-work-arrow {
  width: 42px;
  height: 42px;
  border-radius: 50%;
  border: 1px solid rgba(255,255,255,0.16);
  display: grid;
  place-items: center;
  flex-shrink: 0;
  color: #f3f2f8;
  transition: background 0.3s, color 0.3s, transform 0.4s, border-color 0.3s;
}
.ds-work-card:hover .ds-work-arrow {
  background: linear-gradient(110deg, #7c5cff, #22d3ee 52%, #ff4d9d);
  color: #07070c;
  border-color: transparent;
  transform: rotate(-45deg);
}
